package check;
import burp.api.montoya.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import burp.api.montoya.http.*;import burp.api.montoya.http.message.requests.HttpRequest;
/** Read-only observer of the isolated native Burp instance, never a substitute Burp API. */
public final class SmokeObserver implements BurpExtension {
 public void initialize(MontoyaApi api){
  api.extension().setName("Workbench background verification observer");
  Thread t=new Thread(()->{try{Thread.sleep(5000);Path out=Path.of(System.getProperty("test.run.root"));
   if(Boolean.getBoolean("test.native.http")){List<String> checks=new ArrayList<>();api.scope().includeInScope("http://127.0.0.1:18299/");try(var loader=new java.net.URLClassLoader(new java.net.URL[]{Path.of(System.getProperty("test.release.jar")).toUri().toURL()},getClass().getClassLoader())){Class<?> engine=Class.forName("kr.payloadrunner.Engine",true,loader);for(String path:List.of("/health","/api/diagnostics/boundary/utf8","/api/diagnostics/boundary/gzip","/api/diagnostics/boundary/deflate","/api/diagnostics/boundary/cp949","/api/diagnostics/boundary/empty","/api/diagnostics/boundary/redirect")){
    try{var request=HttpRequest.httpRequestFromUrl("http://127.0.0.1:18299"+path);var result=api.http().sendRequest(request,RequestOptions.requestOptions().withResponseTimeout(3000).withRedirectionMode(RedirectionMode.NEVER));boolean pass=result!=null&&result.response()!=null;String detail="no response";if(pass){var response=result.response();int expected=path.endsWith("redirect")?302:200;Object parsed=engine.getMethod("parse",byte[].class).invoke(null,(Object)response.toByteArray().getBytes());String decoded=parsed.getClass().getMethod("text").invoke(parsed).toString();pass=response.statusCode()==expected;if(Set.of("utf8","gzip","deflate","cp949").stream().anyMatch(path::endsWith))pass&=decoded.contains("한글");if(path.endsWith("empty"))pass&=decoded.isEmpty();detail="HTTP "+response.statusCode()+"; native bytes decoded by release JAR; content-type="+response.headerValue("Content-Type")+"; parser="+engine.getProtectionDomain().getCodeSource().getLocation();}checks.add("{\"path\":"+json(path)+",\"passed\":"+pass+",\"detail\":"+json(detail)+"}");}catch(Throwable e){checks.add("{\"path\":"+json(path)+",\"passed\":false,\"detail\":"+json(e.toString())+"}");}
   }if(System.getProperty("test.release.jar").contains("0.19.0"))NativeBountyChecks.run(api,loader,out);}Files.writeString(out.resolve("native-http-results.json"),"{\"version\":"+json(api.burpSuite().version().toString())+",\"apiImplementation\":"+json(api.getClass().getName())+",\"checks\":["+String.join(",",checks)+"]}",StandardCharsets.UTF_8);}
   Files.writeString(out.resolve("native-user-options.json"),api.burpSuite().exportUserOptionsAsJson(),StandardCharsets.UTF_8);Files.writeString(out.resolve("native-project-options.json"),api.burpSuite().exportProjectOptionsAsJson(),StandardCharsets.UTF_8);Files.writeString(out.resolve("native-ready.txt"),api.burpSuite().version().toString()+"\n"+api.getClass().getName()+"\n",StandardCharsets.UTF_8);System.out.println("NATIVE_BURP_OBSERVER_READY");}catch(Throwable e){e.printStackTrace();}},"Workbench-native-observer");t.setDaemon(true);t.start();
 }
 static String json(String text){return "\""+text.replace("\\","\\\\").replace("\"","\\\"").replace("\r","\\r").replace("\n","\\n")+"\"";}
}
